from __future__ import annotations

import base64
import json
import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

import numpy as np
import SimpleITK as sitk
from PIL import Image


def _segmentation_previews(image, mask, output: Path):
    foreground = np.argwhere(mask > 0)
    center_x = mask.shape[2] // 2 if not len(foreground) else int(np.median(foreground[:, 2]))
    indices = np.clip(np.arange(center_x - 2, center_x + 3), 0, mask.shape[2] - 1)
    paths, roles = [], []
    for number, index in enumerate(indices, 1):
        plane = image[:, :, index].astype(np.float32)
        low, high = np.percentile(plane, (1, 99))
        gray = np.clip((plane - low) / max(high - low, 1e-6), 0, 1)
        rgb = np.repeat((gray * 255).astype(np.uint8)[..., None], 3, axis=2)
        selected = mask[:, :, index] > 0
        rgb[selected] = (
            0.45 * rgb[selected] + 0.55 * np.asarray([255, 70, 40])
        ).astype(np.uint8)
        role = f"sagittal_segmentation_{number:02d}"
        path = output / f"{role}.png"
        Image.fromarray(np.rot90(rgb)).save(path)
        paths.append(str(path))
        roles.append(role)
    return paths, roles


def predict(
    input_path: str,
    model_path: str,
    engine_path: str,
    output_dir: str,
) -> dict:
    source = Path(input_path).resolve()
    output = Path(output_dir).resolve()
    output.mkdir(parents=True, exist_ok=True)
    engine = Path(engine_path).resolve()
    model = Path(model_path).resolve()
    if not source.exists():
        raise FileNotFoundError(source)

    work = Path(tempfile.mkdtemp(prefix="spider_", dir=output))
    try:
        image_dir = work / "datasets" / "Input" / "images"
        experiment = work / "experiments" / "MapleInference"
        weights = experiment / "weights"
        image_dir.mkdir(parents=True)
        weights.mkdir(parents=True)
        scan_path = image_dir / "scan.mha"
        sitk.WriteImage(sitk.ReadImage(str(source)), str(scan_path), True)
        metadata = [{
            "identifier": "scan", "subset": "inference", "filetype": "mha",
            "slice_order_reversed": False, "rescale_intercept": 0,
            "modality": "MR", "ignore_slices_top": 0, "ignore_slices_bottom": 0,
        }]
        (image_dir.parent / "metadata.json").write_text(json.dumps(metadata, indent=2) + "\n")
        shutil.copy2(engine / "arguments.json", experiment / "arguments.json")
        (weights / "999999.pkl").symlink_to(model)

        env = os.environ.copy()
        env["VERSEG_BASEDIR"] = str(work)
        env["VERSEG_EXTDIR"] = str(engine / "devel")
        command = [
            sys.executable, str(engine / "devel" / "Entrypoint.py"),
            "TestSpine", "MapleInference", "--epoch", "999999",
            "--dataset", "Input", "--subset", "inference", "--overwrite",
            "--export_orgres", "--min_size_init", "100", "--min_size_cont", "100",
            "--min_fragment_size", "100", "--keep_only_largest_component",
            "--labeling_penalties",
        ]
        completed = subprocess.run(
            command, cwd=engine, env=env, check=False, text=True,
            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
        )
        if completed.returncode:
            raise RuntimeError(
                "SPIDER inference engine failed:\n" + "\n".join(completed.stdout.splitlines()[-40:])
            )
        result_dir = experiment / "results" / "Input"
        generated_mask = result_dir / "scan_total_segmentation_orgres.mha"
        generated_preview = result_dir / "scan_screenshot.jpg"
        if not generated_mask.exists():
            raise RuntimeError("SPIDER inference did not produce a segmentation")
        mask_path = output / f"{source.stem}_spider_segmentation.mha"
        preview_path = output / f"{source.stem}_spider_preview.jpg"
        shutil.copy2(generated_mask, mask_path)
        shutil.copy2(generated_preview, preview_path)
        source_array = sitk.GetArrayFromImage(sitk.ReadImage(str(source)))
        mask = sitk.GetArrayFromImage(sitk.ReadImage(str(mask_path)))
        preview_files, preview_roles = _segmentation_previews(source_array, mask, output)
        foreground_voxels = int(np.count_nonzero(mask))
        labels = sorted(int(value) for value in np.unique(mask) if value > 0)
        result = {
            "model": "SPIDER iterative lumbar MRI segmentation",
            "segmentation_file": str(mask_path),
            "preview_file": str(preview_path),
            "preview_files": preview_files,
            "preview_roles": preview_roles,
            "preview_b64": base64.b64encode(preview_path.read_bytes()).decode("ascii"),
            "foreground_voxels": foreground_voxels,
            "labels_present": labels,
            "qc_passed": foreground_voxels >= 50000,
            "label_schema": {
                "1-25": "vertebrae C1-L6", "100": "spinal canal",
                "101-125": "incompletely visible vertebrae",
                "201-225": "intervertebral discs following the vertebral label",
            },
            "runtime_log_tail": completed.stdout.splitlines()[-8:],
        }
        (output / f"{source.stem}_result.json").write_text(
            json.dumps({k: v for k, v in result.items() if k != "preview_b64"}, indent=2) + "\n"
        )
        return result
    finally:
        shutil.rmtree(work, ignore_errors=True)


